import React, { useState, useContext, useEffect } from "react";
import GeneralContext from "./GeneralContext";
import { Tooltip, Grow } from "@mui/material";
import {
  BarChartOutlined,
  KeyboardArrowDown,
  KeyboardArrowUp,
  MoreHoriz,
} from "@mui/icons-material";


import { watchlist as staticWatchlist } from "../data/data";
import { DoughnutChart } from "./DoughnoutChart";

const WatchList = () => {

  const [watchlistData, setWatchlistData] = useState(staticWatchlist);


  useEffect(() => {
    const interval = setInterval(() => {
      setWatchlistData((prevData) =>
        prevData.map((stock) => {
          const randomMove = (Math.random() - 0.5) * 1.5; 
          const newPrice = stock.price + randomMove;

          return {
            ...stock,

            price: parseFloat(newPrice.toFixed(2)),
            // Percent update (optional: thoda logic ke saath change kar sakte ho)
            percent: (parseFloat(stock.percent) + (randomMove / 50)).toFixed(2) + "%",
            // Trend change indicator
            isDown: randomMove < 0 ? true : false,
          };
        })
      );
    }, 2500); // Har 2.5 second mein rate badlega

    return () => clearInterval(interval);
  }, []);

  // Chart data setup (ab watchlistData state use karega)
  const labels = watchlistData.map((s) => s.name);
  const data = {
    labels,
    datasets: [
      {
        label: "Price",
        data: watchlistData.map((stock) => stock.price),
        backgroundColor: [
          "rgba(255, 99, 132, 0.5)",
          "rgba(54, 162, 235, 0.5)",
          "rgba(255, 206, 86, 0.5)",
          "rgba(75, 192, 192, 0.5)",
          "rgba(153, 102, 255, 0.5)",
          "rgba(255, 159, 64, 0.5)",
        ],
        borderWidth: 1,
      },
    ],
  };

  return (
    <div className="watchlist-container">
      <div className="search-container">
        <input
          type="text"
          name="search"
          id="search"
          placeholder="Search eg:infy, bse, nifty fut weekly, gold mcx"
          className="search"
        />
        <span className="counts"> {watchlistData.length} / 50</span>
      </div>

      <ul className="list">
        {watchlistData.map((stock, index) => {
          return <WatchListItem stock={stock} key={index} />;
        })}
      </ul>
      <DoughnutChart data={data} />
    </div>
  );
};

// ... Baki WatchListItem aur WatchListActions same rahenge bas unhe 'stock' data state se milega
// ... baaki upar ka code (WatchList component) bilkul same rahega

const WatchListItem = ({ stock }) => {
  const [showWatchlistActions, setShowWatchlistActions] = useState(false);

  return (
    <li 
      onMouseEnter={() => setShowWatchlistActions(true)} 
      onMouseLeave={() => setShowWatchlistActions(false)}
    >
      <div className="item">
        <p className={stock.isDown ? "down" : "up"}>{stock.name}</p>
        <div className="itemInfo">
          <span className="percent">{stock.percent}</span>
          {stock.isDown ? (
            <KeyboardArrowDown className="down" />
          ) : (
            <KeyboardArrowUp className="up" /> 
          )}
          <span className="price">{stock.price}</span>
        </div>
      </div>
      {/* UPDATE: Yahan price={stock.price} bhej rahe hain */}
      {showWatchlistActions && <WatchListActions uid={stock.name} price={stock.price} />}
    </li>
  );
};

const WatchListActions = ({ uid, price }) => { // Price yahan receive kiya
  const generalContext = useContext(GeneralContext);

  return (
    <span className="actions">
      <span>
        <Tooltip title="Buy (B)" placement="top" arrow TransitionComponent={Grow}>
          {/* UPDATE: Context ke function mein price pass kiya */}
          <button className="buy" onClick={() => generalContext.openBuyWindow(uid, price)}>Buy</button>
        </Tooltip>

        <Tooltip title="Sell (S)" placement="top" arrow TransitionComponent={Grow}>
          {/* UPDATE: Context ke function mein price pass kiya */}
          <button className="sell" onClick={() => generalContext.openSellWindow(uid, price)}>Sell</button>
        </Tooltip>

        <Tooltip title="Analytics (A)" placement="top" arrow TransitionComponent={Grow}>
          <button className="action">
            <BarChartOutlined className="icon" />
          </button>
        </Tooltip>
        <Tooltip title="More" placement="top" arrow TransitionComponent={Grow}>
          <button className="action">
            <MoreHoriz className="icon" />
          </button>
        </Tooltip>
      </span>
    </span>
  );
};

export default WatchList;
